function findProcedure(id) { return CLINIC_PROCEDURES.find(p => p.id === id) || CLINIC_PROCEDURES[0]; }

window.CLINIC_PROCEDURES = CLINIC_PROCEDURES;
window.findProcedure = findProcedure;

