// Редкость рыбы (v1.3.12). Заказчик 01.10.2026: «странно, что всех рыб можно
// наловить прям за один день, это плохо с точки зрения игровой механики, надо
// каких-то редких рыб сделать появляющимися с меньшей вероятностью». Раньше шанс
// задавался одним весом (1..12): редкая рыба была лишь в 12 раз реже обычной, и
// коллекция из ста видов закрывалась за пару вечеров. Теперь четыре ступени —
// сначала выбирается ступень со своей вероятностью, потом вид внутри неё.
//   обычная 70% · редкая 20% · очень редкая 8% · легендарная 2%
// Легендарная приходит в ~25 раз реже обычной (0.25% на вид против 3.2%), поэтому
// «Все 100 видов» — цель на недели, а «Ихтиолог» (20 видов) берётся в первый вечер.
const FISH_RARITY = [
  { id: 'common',    name: 'Обычная',      emoji: '⚪', chance: 70, coins: 1,  color: '#9be3b0' },
  { id: 'rare',      name: 'Редкая',       emoji: '🔵', chance: 20, coins: 3,  color: '#7fc4ff' },
  { id: 'epic',      name: 'Очень редкая', emoji: '🟣', chance: 8,  coins: 6,  color: '#c79bff' },
  { id: 'legendary', name: 'Легендарная',  emoji: '🌟', chance: 2,  coins: 15, color: '#ffd93d' }
];

// Ступень по весу вида: 8+ обычная, 5-7 редкая, 3-4 очень редкая, 1-2 легендарная.
// Так разбиты ровно сто видов: 22 обычных, 48 редких, 22 очень редких, 8 легендарных.
function fishRarityOf(sp) {
  const w = (sp && sp.weight) || 1;
  if (w >= 8) return FISH_RARITY[0];
  if (w >= 5) return FISH_RARITY[1];
  if (w >= 3) return FISH_RARITY[2];
  return FISH_RARITY[3];
}

// Случайный вид: сначала ступень редкости, потом вид внутри ступени.
function randomFishSpecies() {
  let roll = Math.random() * 100;
  let tier = FISH_RARITY[FISH_RARITY.length - 1];
  for (const t of FISH_RARITY) { roll -= t.chance; if (roll <= 0) { tier = t; break; } }
  const pool = FISH_SPECIES.filter(f => fishRarityOf(f).id === tier.id);
  const list = pool.length ? pool : FISH_SPECIES;
  return list[Math.floor(Math.random() * list.length)];
}

function findFishSpecies(id) { return FISH_SPECIES.find(f => f.id === id) || null; }
function findSeaFriend(id) { return SEA_FRIENDS.find(f => f.id === id) || null; }

// Внешний «портрет» рыбки (v1.3.12). Заказчик: «чтобы рыбки были разной формы,
// размеров, и чтобы они были не только одноцветные, но и некоторые разноцветные
// с разными плавниками». У вида можно задать поля прямо в данных — shape (slim/
// deep/flat/normal), tail (fan/fork/round/streamer), fin (sail/spiky/low),
// pattern (stripes/spots/none) и accent (цвет полосок/пятен). Остальным видам
// набор достаётся по устойчивому «хэшу» id: у каждой рыбки свой силуэт, хвост,
// плавник и узор — и они одинаковые от игры к игре, вид узнаётся.
const FISH_SHAPES = ['normal', 'slim', 'deep', 'flat'];
const FISH_TAILS = ['fan', 'fork', 'round', 'streamer'];
const FISH_FINS = ['sail', 'spiky', 'low'];
const FISH_PATTERNS = ['none', 'stripes', 'spots'];
function fishVariety(sp) {
  const id = String((sp && sp.id) || 'x');
  let x = 0;
  for (let i = 0; i < id.length; i++) x = (x * 31 + id.charCodeAt(i)) >>> 0;
  const pick = (arr, shift) => arr[(x >>> shift) % arr.length];
  return {
    shape: sp.shape || pick(FISH_SHAPES, 0),
    tail: sp.tail || pick(FISH_TAILS, 3),
    fin: sp.fin || pick(FISH_FINS, 6),
    pattern: sp.pattern || pick(FISH_PATTERNS, 9),
    accent: sp.accent || null
  };
}

// Подпись проплывающего обитателя: имя и факт, без приписки «не ловим».
function seaFriendHint(id) {
  const f = findSeaFriend(id);
  if (!f) return '';
  return f.name + ': ' + f.fact;
}

window.FISH_SPECIES = FISH_SPECIES;
window.SEA_FRIENDS = SEA_FRIENDS;
window.randomFishSpecies = randomFishSpecies;
window.findFishSpecies = findFishSpecies;
window.findSeaFriend = findSeaFriend;
window.seaFriendHint = seaFriendHint;

